import {ShipLayer} from './ship-layer.js';
import {DRIVES} from './ship-data.js';
import {formatGameDate} from './time-control.js';
const STATES={idle:'대기',turning:'선회',charging:'드라이브 충전',propulsion:'행성권 추진',cruising:'순항'};
export function formatDuration(seconds){if(!Number.isFinite(seconds))return '—';seconds=Math.max(0,Math.ceil(seconds));if(seconds<60)return seconds+'초';if(seconds<3600)return Math.floor(seconds/60)+'분 '+seconds%60+'초';if(seconds<86400)return Math.floor(seconds/3600)+'시간 '+Math.floor(seconds%3600/60)+'분';return Math.floor(seconds/86400)+'일 '+Math.floor(seconds%86400/3600)+'시간';}
export class ShipUI {
  constructor(viewer,fleet,simulation,{notify=()=>{},sync=()=>{}}={}){
    this.viewer=viewer;this.fleet=fleet;this.simulation=simulation;this.notify=notify;this.sync=sync;this.selectedId=null;this.targetMode=false;this.abort=new AbortController();this.root=document.createElement('div');this.root.className='fleet-ui';this.root.innerHTML=`<nav class="fleet-roster" aria-label="시작 함대"><button id="fleet-toggle" aria-expanded="false">함대 <span>3</span></button><div id="fleet-list" hidden></div></nav><aside class="ship-info" hidden aria-label="선택 함선 정보"><header><small>SHIP / M1a</small><button id="ship-close" aria-label="함선 선택 해제">×</button></header><strong id="ship-name"></strong><p id="ship-design"></p><dl><div><dt>상태</dt><dd id="ship-state"></dd></div><div><dt>목적지</dt><dd id="ship-target"></dd></div><div><dt>도착</dt><dd id="ship-eta"></dd></div><div><dt>현실 대기</dt><dd id="ship-real-eta"></dd></div></dl><button id="ship-focus">함선 확대 ↗</button><button id="ship-replot" hidden>목적지 변경 ↗</button><label><input id="ship-auto-pause" type="checkbox">도착 시 일시정지</label></aside><div class="ship-command" hidden><div id="ship-progress" hidden><span></span><progress max="1" value="0"></progress></div><button id="ship-move" aria-label="이동 지점 선택">➜</button><button class="ship-placeholder" disabled aria-label="탐사: M2 예정">⌕</button><button class="ship-placeholder" disabled aria-label="화물: M5 예정">◇</button></div><div class="ship-target-prompt" hidden><button id="ship-back" aria-label="이동 지점 선택 취소">←</button><span>이동 지점 선택</span><small>행성 · 소행성 · 꼭짓점 · 아군</small></div>`;
    viewer.container.parentElement.append(this.root);this.$=s=>this.root.querySelector(s);const listen=(s,event,fn)=>this.$(s).addEventListener(event,fn,{signal:this.abort.signal});
    this.$('#fleet-toggle span').textContent=fleet.ships.size;for(const ship of fleet.ships.values()){const b=document.createElement('button');b.textContent=ship.name;b.dataset.fleetShip=ship.id;b.addEventListener('click',()=>this.select(ship.id),{signal:this.abort.signal});this.$('#fleet-list').append(b);}
    listen('#fleet-toggle','click',()=>{const open=this.$('#fleet-list').hidden;this.$('#fleet-list').hidden=!open;this.$('#fleet-toggle').setAttribute('aria-expanded',String(open));});
    listen('#ship-close','click',()=>viewer.select(null));listen('#ship-focus','click',()=>this.layer.focus(this.selectedId));listen('#ship-move','click',()=>{if(this.fleet.ships.get(this.selectedId)?.plan)this.cancel();else this.setTargetMode(true);});listen('#ship-back','click',()=>this.setTargetMode(false));listen('#ship-replot','click',()=>this.setTargetMode(true));listen('#ship-auto-pause','change',e=>{fleet.pauseOnArrival=e.target.checked;});
    this.layer=new ShipLayer(viewer,fleet,{onShip:id=>this.select(id),onTarget:target=>this.order(target)});viewer.navigation=this;
    fleet.onArrival=event=>notify(`${event.ship.name} · ${event.targetName} 도착`);
  }
  select(id){this.viewer.select(null);this.viewer.onSelection({kind:'ship',shipId:id,systemId:this.fleet.context.systemId});}
  observeSelection(selection){this.layer.followId=null;this.layer.lastFollow=null;this.selectedId=selection?.kind==='ship'?selection.shipId:null;this.layer.select(this.selectedId);this.setTargetMode(false);this.$('#fleet-list').hidden=true;this.$('#fleet-toggle').setAttribute('aria-expanded','false');this.update();}
  setTargetMode(value){this.targetMode=!!value&&!!this.selectedId;this.layer.targetMode=this.targetMode;this.$('.ship-target-prompt').hidden=!this.targetMode;this.$('.ship-command').hidden=this.targetMode||!this.selectedId;this.$('.ship-info').hidden=this.targetMode||!this.selectedId||!!this.viewer.surface;this.viewer.container.parentElement.classList.toggle('choosing-ship-target',this.targetMode);}
  order(target){if(!this.selectedId)return false;this.sync();try{this.fleet.order(this.selectedId,target);this.setTargetMode(false);this.update();return true;}catch(error){this.notify(error.message);return false;}}
  cancel(){if(this.targetMode){this.setTargetMode(false);return;}this.sync();if(this.fleet.cancel(this.selectedId))this.notify('이동 취소 · 현재 위치에서 대기');this.update();}
  handleClick(x,y,type){if(this.targetMode){const target=this.layer.pickTarget(x,y,type);if(target)this.order(target);else this.notify('강조된 이동 지점을 선택하세요.');return true;}const id=this.layer.pickShip(x,y,type);if(id){this.select(id);return true;}if(this.selectedId){this.viewer.select(null);return true;}return false;}
  handleBodyClick(id){if(!this.targetMode)return false;this.order({kind:'body',id});return true;}
  handleRightClick(x,y,type){if(!this.selectedId||this.viewer.surface)return;const target=this.layer.pickTarget(x,y,type);if(target)this.order(target);else this.notify('천체·소행성·섹터 꼭짓점·아군 함선을 지정하세요.');}
  beforeCameraUpdate(){this.layer.beforeCameraUpdate();}
  updateLayer(){this.layer.update();}
  update(){const ship=this.fleet.ships.get(this.selectedId),visible=!!ship&&!this.viewer.surface;this.$('.ship-info').hidden=!visible||this.targetMode;this.$('.fleet-roster').hidden=!!this.viewer.surface||!this.fleet.ships.size;this.$('.ship-command').hidden=!visible||this.targetMode;this.$('.ship-target-prompt').hidden=!visible||!this.targetMode;if(!visible)return;
    this.$('#ship-name').textContent=ship.name;this.$('#ship-design').textContent=`${ship.design.hullClass} · ${DRIVES[ship.design.driveId].name} · ${ship.design.reactor}`;this.$('#ship-state').textContent=STATES[ship.state];this.$('#ship-target').textContent=ship.plan?.target.name??ship.locationName;
    this.$('#ship-replot').hidden=!ship.plan;const plan=ship.plan,remaining=plan?Math.max(0,plan.arrivalAt-this.fleet.now):0;
    this.$('#ship-eta').textContent=plan?formatGameDate(this.fleet.context.epochISO,plan.arrivalAt/86400)+' UTC':'—';this.$('#ship-real-eta').textContent=plan?(this.simulation.paused?'일시정지 · ': '')+formatDuration(remaining/(10*this.simulation.effectiveSpeed)):`${ship.attachment?'천체 공전 추종':'항성계 좌표 고정'}`;
    const move=this.$('#ship-move');move.textContent=plan?'×':'➜';move.setAttribute('aria-label',plan?'이동 취소':'이동 지점 선택');this.$('#ship-progress').hidden=!plan||!['turning','charging'].includes(ship.state);
    if(plan){const stage=plan.stages.find(s=>this.fleet.now<s.end-1e-8)??plan.stages.at(-1);this.$('#ship-progress span').textContent=`${STATES[ship.state]} · ${formatDuration(stage.end-this.fleet.now)} / 우회 ${plan.waypoints.length}`;this.$('#ship-progress progress').value=(this.fleet.now-stage.start)/Math.max(1e-9,stage.end-stage.start);}
  }
  dispose(){if(this.viewer.navigation===this)this.viewer.navigation=null;this.abort.abort();this.layer.dispose();this.root.remove();this.viewer.container.parentElement.classList.remove('choosing-ship-target');}
}
